/**
 * Independent verification: the Rust backend's passkey attestation +
 * assertion bytes are validated by @simplewebauthn/server, a third-party
 * implementation. Fixture generated by passkey_vectors.rs (UPDATE_FIXTURES=1).
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  verifyAuthenticationResponse,
  verifyRegistrationResponse,
} from "@simplewebauthn/server";

const FIXTURE =
  "../../../desktop/src-tauri/tests/fixtures/passkey_vectors.json";
const v = JSON.parse(readFileSync(new URL(FIXTURE, import.meta.url), "utf8"));

describe("passkey fixture vectors", () => {
  it("registration verifies with expected origin/rp/challenge", async () => {
    const r = v.registration;
    const verification = await verifyRegistrationResponse({
      response: {
        id: r.credentialId,
        rawId: r.credentialId,
        type: "public-key",
        response: {
          clientDataJSON: r.clientDataJSON,
          attestationObject: r.attestationObject,
        },
        clientExtensionResults: {},
        authenticatorAttachment: "platform",
      },
      expectedChallenge: r.challenge,
      expectedOrigin: v.origin,
      expectedRPID: v.rpId,
      requireUserVerification: true,
    });
    expect(verification.verified).toBe(true);
    const cred = verification.registrationInfo?.credential;
    expect(cred?.publicKey).toBeDefined();
    expect(cred?.counter).toBe(0);

    // assertion verifies with the credential public key from registration
    const a = v.assertion;
    const auth = await verifyAuthenticationResponse({
      response: {
        id: r.credentialId,
        rawId: r.credentialId,
        type: "public-key",
        response: {
          clientDataJSON: a.clientDataJSON,
          authenticatorData: a.authenticatorData,
          signature: a.signature,
        },
        clientExtensionResults: {},
        authenticatorAttachment: "platform",
      },
      expectedChallenge: a.challenge,
      expectedOrigin: v.origin,
      expectedRPID: v.rpId,
      credential: {
        id: r.credentialId,
        publicKey: cred!.publicKey,
        counter: cred!.counter,
        transports: cred!.transports,
      },
      requireUserVerification: true,
    });
    expect(auth.verified).toBe(true);
  });
});
